import {PLAYERS,DIFFICULTY,CATEGORIES} from './players.mjs';
import * as E from './engine.mjs';
import {PLAYER_PHOTOS} from './player-photos.mjs';

const $=selector=>document.querySelector(selector);
const main=$('#main');
const SAVE_KEY='kalma-w-bas.match.v1';
const SOUND_KEY='kalma-w-bas.sound.v1';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=value=>new Intl.NumberFormat('ar-JO').format(value);
const I={
 arrow:'<path d="M19 12H5m7 7-7-7 7-7"/>',
 play:'<path d="m9 5 10 7-10 7z"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
 switch:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',
 trophy:'<path d="M7 3h10v5a5 5 0 0 1-10 0V3Zm0 2H3v3a4 4 0 0 0 5 4m9-7h4v3a4 4 0 0 1-5 4M12 13v6m-5 2h10M9 19h6"/>',
 ball:'<circle cx="12" cy="12" r="9"/><path d="m12 7 5 3-2 6H9l-2-6 5-3ZM12 3v4M4 9l3 1m-1 9 3-3m9 3-3-3m5-7-3 1"/>',
 sound:'<path d="m11 4-6 5H2v6h3l6 5V4Zm5 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
 muted:'<path d="m11 4-6 5H2v6h3l6 5V4Zm5 5 6 6m0-6-6 6"/>',
 users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',
 reset:'<path d="M3 4v6h6M3 10a9 9 0 1 1 1 8"/>',
 pencil:'<path d="m15 4 5 5M4 20l1-6L17 2l5 5L10 19l-6 1Z"/>',
 chevron:'<path d="m8 4 8 8-8 8"/>',
 flag:'<path d="M5 22V3m0 0c5-5 9 5 15 0v10c-6 5-10-5-15 0"/>',
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[name]||I.ball}</svg>`;
function photoFor(player){
  if(PLAYER_PHOTOS[player.id])return PLAYER_PHOTOS[player.id];
  if(player.tags?.includes('custom')){const known=PLAYERS.find(p=>E.normalizeWord(p.name)===E.normalizeWord(player.name));return known?PLAYER_PHOTOS[known.id]:null;}
  return null;
}
function playerPortrait(player){
  const photo=photoFor(player);if(!photo)return '';
  return `<figure class="portrait-frame"><img class="player-photo" src="${escape(photo.src)}" alt="${escape(player.name)}" width="360" height="360" decoding="async" draggable="false"><span class="portrait-failure" role="status">تعذّر تحميل الصورة</span><span class="portrait-corner" aria-hidden="true">★</span></figure>`;
}
function photoCredit(player){const photo=photoFor(player);if(!photo)return '';const owner=PLAYER_PHOTOS[player.id]?player.id:PLAYERS.find(p=>PLAYER_PHOTOS[p.id]===photo)?.id;return `<a class="photo-credit" href="/photo-credits.html#${escape(owner||'')}" target="_blank" rel="noopener">مصدر الصورة وحقوقها ↗</a>`;}
function preloadPortrait(player){const photo=photoFor(player);if(photo&&typeof Image!=='undefined'){const image=new Image();image.src=photo.src;}}
const defaultConfig={teams:[{name:'الصقور',members:['اللاعب ١','اللاعب ٢']},{name:'النمور',members:['اللاعب ٣','اللاعب ٤']}],seconds:90,target:5,category:'all',difficulty:'all',customNames:''};
let match=null,view='home',setupConfig=structuredClone(defaultConfig),revealed=false,revealTimeout,toastTimeout,sound=true,audioContext,lastBeep=-1,modalCallback=null;
try{sound=localStorage.getItem(SOUND_KEY)!=='off';const saved=JSON.parse(localStorage.getItem(SAVE_KEY));if(E.validSavedState(saved)){match=saved;if(match.phase==='playing')match=E.pause(match);}}catch{}
function save(){try{if(match)localStorage.setItem(SAVE_KEY,JSON.stringify(match));}catch{toast('تعذّر حفظ المباراة على هذا المتصفح. أبقوا الصفحة مفتوحة.');}}
function update(state){match=state;save();render();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function announce(message){$('#announcer').textContent=message;}
function soundIcon(){$('#sound-button').innerHTML=icon(sound?'sound':'muted');$('#sound-button').setAttribute('aria-pressed',String(sound));$('#sound-button').setAttribute('aria-label',sound?'إيقاف الصوت':'تشغيل الصوت');}
function beep(type='click'){
  if(!sound)return;
  try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const notes=type==='win'?[523,659,784]:type==='end'?[440,330,220]:[type==='tick'?650:500];notes.forEach((freq,index)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain(),at=audioContext.currentTime+index*.14;oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.type='sine';oscillator.frequency.value=freq;gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(.1,at+.02);gain.gain.exponentialRampToValueAtTime(.0001,at+.13);oscillator.start(at);oscillator.stop(at+.15);});}catch{}
}
function render(){
  hideSecret();soundIcon();
  document.body.dataset.view=view;
  main.innerHTML=view==='setup'?setupView():view==='match'&&match?matchView():homeView();
  document.title=view==='match'&&match?`${match.config.teams[0].name} ${match.scores[0]} : ${match.scores[1]} ${match.config.teams[1].name} — كلمة وبس`:'كلمة وبس — مين اللاعب؟';
  if(view==='setup'){updatePoolPreview();bindSetup();}
  if(view==='match'&&match?.phase==='reveal')bindReveal();
  if(view==='match'&&match?.phase==='playing')paintTimer();
}
function go(next){view=next;render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}

function pitchIllustration(){return `<div class="hero-art usa-poster" aria-hidden="true"><div class="poster-top"><span>THE ONE-WORD CUP</span><span>★ ★ ★</span></div><div class="poster-year" dir="ltr"><strong>USA</strong><span>19<span>94</span></span></div><svg class="poster-stripes" viewBox="0 0 500 450" preserveAspectRatio="none"><path d="M-70 300C80 110 300 420 560 130"/><path d="M-70 355C80 165 300 475 560 185"/><path d="M-70 410C80 220 300 530 560 240"/></svg><span class="poster-star s1">★</span><span class="poster-star s2">★</span><span class="poster-star s3">★</span><div class="retro-player-card"><div class="retro-card-top"><span>بطاقة اللاعب السرّية</span><b>01</b></div><div class="retro-jersey"><svg viewBox="0 0 220 195"><defs><clipPath id="shirt"><path d="m76 16-47 20L7 82l40 19 16-25v110h94V76l16 25 40-19-22-46-47-20c-3 16-15 24-34 24S79 32 76 16Z"/></clipPath></defs><path d="m76 16-47 20L7 82l40 19 16-25v110h94V76l16 25 40-19-22-46-47-20c-3 16-15 24-34 24S79 32 76 16Z" fill="#254cb5" stroke="#152c68" stroke-width="3"/><g clip-path="url(#shirt)"><path d="m-10 71 240 100m-240-63 240 100m-240-63 240 100" stroke="#fff9eb" stroke-width="13"/><path d="m-10 83 240 100m-240-63 240 100m-240-63 240 100" stroke="#dd4149" stroke-width="13"/><path d="m51 39 3 6 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1Zm119 0 3 6 7 1-5 5 1 7-6-4-6 4 1-7-5-5 7-1Z" fill="#fff9eb"/></g><path d="M76 16c6 33 61 33 68 0" fill="none" stroke="#fff9eb" stroke-width="7"/><path d="M76 16c6 33 61 33 68 0" fill="none" stroke="#dd4149" stroke-width="3"/><path d="M96 73c3-15 30-15 33 1 4 17-19 19-19 34" fill="none" stroke="#fff9eb" stroke-width="9" stroke-linecap="round"/><circle cx="110" cy="124" r="5" fill="#fff9eb"/></svg></div><div class="retro-card-bottom"><b>مين اللاعب؟</b><span>ONE WORD. ONE GOAL.</span></div></div><div class="poster-ticket"><div><small>التلميح الأول</small><b>«يسار»</b></div><span>ADMIT<br><strong>4+1</strong></span></div><div class="poster-ball"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="47" fill="#fff9eb" stroke="#142b69" stroke-width="2"/><path d="m50 27 22 16-8 26H36l-8-26Z" fill="#142b69"/><path d="m50 3 7 13-7 11-7-11Zm44 32-15 1-7 7 5 15 19 7M77 88l-2-16-11-3-7 16 1 11M23 88l2-16 11-3 7 16-1 11M6 35l15 1 7 7-5 15L4 65" fill="#142b69"/><path d="m21 36 22-20m14 0 22 20m-2 22-2 14M57 85H43M25 72l-2-14" stroke="#142b69" fill="none"/><path d="m50 38 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z" fill="#fff9eb"/></svg></div><div class="poster-footer"><span>SUMMER OF FOOTBALL</span><span>EST. 1994 / PLAY TODAY</span></div></div>`;}
function homeView(){const active=match&&match.phase!=='finished';return `<section class="home-hero"><div class="hero-copy"><div class="eyebrow"><span class="tiny-ball">${icon('ball')}</span> بروح مونديال أمريكا ٩٤</div><h1>كلمة <span class="outlined-word">واحدة.</span><br>وحماس <span class="lime-underline">مونديال.</span></h1><p class="hero-description">تعرف اللاعب من تلميح؟ جمّع أصحابك، كوّنوا فريقين، وخلّوا الحكم يدير الحماس. كل دور كلمة… والباقي على شطارتكم.</p><div class="hero-actions"><button class="btn btn-dark btn-lg" data-action="${active?'resume-match':'setup'}">${active?'كمّلوا المباراة':'يلا نلعب'} ${icon('arrow')}</button>${active?'<button class="text-btn" data-action="setup">مباراة جديدة</button>':'<span class="no-fuss">جهاز واحد.<br>والكل بالملعب.</span>'}</div>${active?`<div class="resume-strip"><span class="live-dot"></span> مباراة محفوظة <b>${escape(match.config.teams[0].name)} ${num(match.scores[0])} — ${num(match.scores[1])} ${escape(match.config.teams[1].name)}</b></div>`:''}<div class="hero-facts"><span>${icon('users')} ٤ لاعبين + حكم</span><span>${icon('clock')} جولات سريعة</span><span>${icon('ball')} ${num(PLAYERS.length)} لاعبًا</span></div></div>${pitchIllustration()}</section><div class="retro-marquee" aria-hidden="true"><span>ONE WORD</span> ★ <span>فريقين</span> ★ <span>ONE GOAL</span> ★ <span>كلمة واحدة</span> ★ <span>GAME ON</span> ★ <span>نفس الحماس</span></div><section class="how-section" aria-labelledby="how-title"><div class="section-heading"><div><span class="eyebrow small">من أول كلمة… بتفهموها</span><h2 id="how-title">قوانين قليلة. حماس كثير.</h2></div><button class="text-btn" data-action="rules">القواعد كاملة ${icon('arrow')}</button></div><div class="steps-grid"><article class="step-card"><span class="step-num">01</span><div class="step-icon">${icon('users')}</div><h3>قسّموا الصحبة</h3><p>فريقين، شخصين بكل فريق، وحكم يمسك الجهاز ويدير اللعب.</p></article><article class="step-card"><span class="step-num">02</span><div class="step-icon">${icon('eye')}</div><h3>شوفه… وخبّيه</h3><p>شخص من كل فريق يشوف صورة اللاعب واسمه بالسر. زميله ما يشوفهم.</p></article><article class="step-card"><span class="step-num">03</span><div class="step-icon">${icon('trophy')}</div><h3>كلمة بتجيب هدف</h3><p>تبادلوا التلميحات، كلمة كل دور. أول فريق يخمّن صح، إله نقطة.</p></article></div></section><section class="bottom-callout"><div><span class="mini-stars">✦ ✦ ✦</span><h3>من سحر التسعينات… لنجوم اليوم.</h3><p>أسماء من أوروبا والملاعب العربية، ومستويات تناسب كل الشلّة.</p></div><button class="btn btn-outline" data-action="setup">جهّزوا فريقكم ${icon('arrow')}</button></section>`;}

function chip(name,value,label,selected){return `<label class="choice"><input type="radio" name="${name}" value="${value}" ${String(value)===String(selected)?'checked':''}><span>${label}</span></label>`;}
function setupView(){const c=setupConfig;return `<section class="setup-page narrow-page"><button class="back-button" data-action="home">${icon('chevron')} الرئيسية</button><div class="page-title"><span class="eyebrow">قبل صافرة البداية</span><h1>مين نازل الملعب؟</h1><p>سمّوا فريقكم، واختاروا شكل التحدّي. الحكم يمسك الجهاز.</p></div><form id="setup-form"><div class="team-setup-grid">${c.teams.map((team,i)=>`<section class="team-setup team-${i}"><div class="team-title"><div class="team-emblem">${icon(i?'flag':'ball')}</div><span>الفريق ${i?'الثاني':'الأول'}</span><span class="team-color-dot"></span></div><label class="field"><span>اسم الفريق</span><input name="team${i}" value="${escape(team.name)}" maxlength="24" placeholder="${i?'النمور':'الصقور'}" autocomplete="off"></label><div class="members-grid">${team.members.map((member,j)=>`<label class="field"><span>اللاعب ${j?'الثاني':'الأول'}</span><input name="member${i}${j}" value="${escape(member)}" maxlength="24" placeholder="اسم اللاعب" autocomplete="off"></label>`).join('')}</div><p class="field-note">${icon('switch')} الأدوار بتتبدّل تلقائيًا كل جولة</p></section>`).join('')}</div><section class="settings-card"><div class="settings-heading">${icon('ball')} <h2>اضبطوا التحدّي</h2></div><div class="settings-row"><div><h3>من أي ملاعب؟</h3><p>اختاروا مجموعة أسماء</p></div><div class="choices categories">${Object.entries(CATEGORIES).map(([key,label])=>chip('category',key,label,c.category)).join('')}</div></div><div class="settings-row"><div><h3>قدّيش بتعرفوا كورة؟</h3><p>الصعوبة حسب شهرة الأسماء</p></div><div class="choices">${[['all','مزيج'],...Object.entries(DIFFICULTY)].map(([key,label])=>chip('difficulty',key,label,c.difficulty)).join('')}</div></div><div class="settings-row"><div><h3>وقت الجولة</h3><p>مؤقّت مشترك للفريقين</p></div><div class="choices">${[60,90,120,0].map(n=>chip('seconds',n,n?`${num(n)} ثانية`:'بدون وقت',c.seconds)).join('')}</div></div><div class="settings-row"><div><h3>نقاط الفوز</h3><p>أول فريق يوصل، يكسب</p></div><div class="choices">${[5,10,15].map(n=>chip('target',n,`${num(n)} نقاط`,c.target)).join('')}</div></div><details class="custom-details" ${c.category==='custom'?'open':''}><summary>${icon('pencil')} أضيفوا لاعبين من عندكم <span>اختياري</span></summary><label class="field"><span>كل اسم في سطر لوحده — حتى ١٥٠ اسمًا</span><textarea name="customNames" rows="5" maxlength="12000" placeholder="مثلاً:&#10;عبدالله السعيد&#10;أحمد فتحي">${escape(c.customNames)}</textarea></label><p class="field-note">تُضاف الأسماء للمجموعة المختارة. اختاروا «أسماؤكم الخاصة» للّعب بها فقط.</p></details></section><div class="setup-bottom"><div class="pool-preview">${icon('check')} <span id="pool-count"></span><small>بدون تكرار خلال المباراة</small></div><button class="btn btn-dark btn-lg" type="submit">جاهزين… بلّش ${icon('arrow')}</button></div><p class="privacy-note">اللعبة حضورية على جهاز واحد. إعداداتكم ونتائجكم تنحفظ في هذا المتصفح.</p></form></section>`;}
function configFromForm(){const form=$('#setup-form');if(!form)return setupConfig;const f=new FormData(form);return {teams:[0,1].map(i=>({name:String(f.get(`team${i}`)||'').trim()||defaultConfig.teams[i].name,members:[0,1].map(j=>String(f.get(`member${i}${j}`)||'').trim()||defaultConfig.teams[i].members[j])})),seconds:Number(f.get('seconds')),target:Number(f.get('target')),category:String(f.get('category')),difficulty:String(f.get('difficulty')||setupConfig.difficulty||'all'),customNames:String(f.get('customNames')||'')};}
function updatePoolPreview(){setupConfig=configFromForm();const count=E.makePool(PLAYERS,setupConfig).length;$('#pool-count').textContent=`${num(count)} لاعبًا جاهزًا للتحدّي`;$('[type="submit"]').disabled=count<2;const customOnly=setupConfig.category==='custom';document.querySelectorAll('[name="difficulty"]').forEach(el=>{el.disabled=customOnly;});if(customOnly)$('.custom-details').open=true;}
function bindSetup(){const form=$('#setup-form');form.addEventListener('input',updatePoolPreview);form.addEventListener('change',updatePoolPreview);form.addEventListener('submit',e=>{e.preventDefault();setupConfig=configFromForm();const start=()=>{try{match=E.createMatch(setupConfig,PLAYERS);save();beep();go('match');}catch(error){toast(error.message);}};if(match&&match.phase!=='finished')confirmDialog('نبدأ مباراة جديدة؟','رح تبدأ النقاط من الصفر وتنتهي المباراة المحفوظة.','ابدأ مباراة جديدة',start);else start();});}

function scoreboard(){return `<div class="scoreboard">${match.config.teams.map((team,i)=>`<div class="score-team team-${i}"><div class="score-emblem">${icon(i?'flag':'ball')}</div><div class="score-name"><b>${escape(team.name)}</b><small>${escape(team.members.join(' و '))}</small></div><strong>${num(match.scores[i])}</strong></div>${i===0?`<div class="score-divider"><span>إلى ${num(match.config.target)}</span><small>نقاط</small></div>`:''}`).join('')}</div>`;}
function matchTop(){return `<div class="game-top"><button class="back-button" data-action="home">${icon('chevron')} الرئيسية</button><div class="round-tag"><span class="live-dot"></span> الجولة ${num(match.current.number)}</div><button class="text-btn muted" data-action="end-match">إنهاء المباراة</button></div>`;}
function matchView(){return `<section class="game-page narrow-page">${match.phase!=='finished'?matchTop():''}${scoreboard()}${({reveal:revealView,ready:readyView,playing:playingView,result:resultView,finished:finishedView}[match.phase])()}</section>`;}
function revealView(){const c=match.current,t=c.revealStep,name=E.cluePerson(match,t);return `<div class="game-stage reveal-stage"><div class="step-pills"><span class="${t===0?'active':'done'}">${t===0?'١':icon('check')} كشف الفريق الأول</span><i></i><span class="${t===1?'active':''}">٢ كشف الفريق الثاني</span></div><div class="page-title compact"><span class="eyebrow">بعيدًا عن عيون المخمّنين</span><h1>الجهاز مع <em class="team-text-${t}">${escape(name)}</em></h1><p>من فريق <b>${escape(match.config.teams[t].name)}</b>. خَلّي زميلك <b>${escape(E.guessPerson(match,t))}</b> يبعد عينه.</p></div><div class="secret-card ${photoFor(c.player)?'with-portrait':''}" id="secret-card"><div id="secret-content"><div class="secret-lock">${icon('lock')}</div><h2>اللاعب مخبّأ</h2><p>شخص واحد فقط من كل فريق يشوف اللاعب</p></div><button class="reveal-button" id="reveal-button" aria-label="اضغط مطولًا لرؤية صورة اللاعب واسمه" style="touch-action:none">${icon('eye')} اضغط مطوّلًا للكشف</button><span class="secret-footnote">ارفع إصبعك… تختفي الصورة والاسم فورًا</span></div><div class="reveal-actions"><button class="btn btn-dark btn-lg" data-action="acknowledge" id="acknowledge" ${!c.seen[t]?'disabled':''}>${t===0?'حفظت اللاعب… سلّم الجهاز':'حفظت اللاعب… رجّع الجهاز للحكم'} ${icon('arrow')}</button><button class="text-btn muted" data-action="replace-player">الحكم: غيّر اللاعب</button></div><p class="safe-note">${icon('lock')} نفس اللاعب للفريقين. لا تحكوا أي تلميح قبل البداية.</p></div>`;}
function bindReveal(){preloadPortrait(match.current.player);const button=$('#reveal-button');button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture?.(e.pointerId);showSecret();});for(const type of ['pointerup','pointercancel','pointerleave','lostpointercapture'])button.addEventListener(type,hideSecret);button.addEventListener('contextmenu',e=>e.preventDefault());button.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();showSecret();}});button.addEventListener('keyup',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();hideSecret();}});button.addEventListener('blur',hideSecret);}
function showSecret(){if(view!=='match'||match?.phase!=='reveal')return;revealed=true;match=E.markSeen(match);save();$('#secret-card').classList.add('revealed');$('#secret-content').innerHTML=`<span class="secret-eyebrow">احفظ اللاعب… وخليه سر</span>${playerPortrait(match.current.player)}<h2 class="player-name">${escape(match.current.player.name)}</h2><span class="player-type">${match.current.player.difficulty==='custom'?'من قائمتكم الخاصة':DIFFICULTY[match.current.player.difficulty]}</span>`;$('#acknowledge').disabled=false;clearTimeout(revealTimeout);revealTimeout=setTimeout(hideSecret,10000);}
function hideSecret(){revealed=false;clearTimeout(revealTimeout);const card=$('#secret-card');if(card){card.classList.remove('revealed');$('#secret-content').innerHTML=`<div class="secret-lock">${icon('lock')}</div><h2>اللاعب مخبّأ</h2><p>شخص واحد فقط من كل فريق يشوف اللاعب</p>`;}}
function readyView(){return `<div class="game-stage ready-stage"><div class="center-icon lime">${icon('check')}</div><div class="page-title compact"><span class="eyebrow">السر صار مع الاثنين</span><h1>يا حكم… صفّر!</h1><p>الجهاز الآن مع الحكم. الصور والأسماء مخبّأة والكل جاهز.</p></div><div class="roles-grid">${match.config.teams.map((team,i)=>`<div class="role-card team-${i}"><span class="team-chip">${escape(team.name)}</span><div><b>${escape(E.cluePerson(match,i))}</b><small>يعطي كلمة</small></div>${icon('arrow')}<div><b>${escape(E.guessPerson(match,i))}</b><small>يخمّن اللاعب</small></div></div>`).join('')}</div><div class="ready-settings"><span>${icon('clock')} ${match.config.seconds?`${num(match.config.seconds)} ثانية`:'بدون مؤقّت'}</span><span>${icon('flag')} ${escape(match.config.teams[match.current.turn].name)} يبدأ</span></div><button class="btn btn-dark btn-lg start-round" data-action="start-round">ابدأ الجولة ${icon('play')}</button><p class="safe-note">كلمة واحدة في كل دور، ثم الفريق الثاني. أول إجابة صح تكسب نقطة.</p><button class="text-btn muted" data-action="replace-player">غيّر اللاعب</button></div>`;}
function timeLabel(seconds){if(seconds===null)return '∞';const total=Math.ceil(seconds);return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`;}
function playingView(){const c=match.current,t=c.turn;return `<div class="playing-stage"><div class="timer-section"><div class="timer-copy"><span class="eyebrow">${c.paused?'استراحة قصيرة':'الوقت يمشي… والاسم مخبّأ'}</span><h2>${c.paused?'الجولة متوقّفة':'كلمة منك. تخمينة من زميلك.'}</h2></div><div class="timer-area"><button class="icon-btn pause-btn" data-action="pause" aria-label="${c.paused?'متابعة الجولة':'إيقاف المؤقّت مؤقتًا'}">${icon(c.paused?'play':'pause')}</button><div class="timer" id="timer" role="timer" aria-label="الوقت المتبقي" dir="ltr">${timeLabel(E.remaining(match))}</div></div></div><div class="time-track"><div id="time-progress"></div></div>${c.paused?`<div class="paused-overlay"><div class="center-icon">${icon('pause')}</div><h3>خذوا نفس…</h3><p>المؤقّت واقف. كمّلوا لما تكونوا جاهزين.</p><button class="btn btn-dark" data-action="pause">متابعة الجولة ${icon('play')}</button></div>`:`<div class="turn-card team-${t}"><div class="turn-heading"><span class="team-chip">دور ${escape(match.config.teams[t].name)}</span><span class="clue-counter">${num(c.clues[0]+c.clues[1]+1)} <small>التلميح</small></span></div><div class="turn-instruction"><div class="turn-bubble">${icon('pencil')}</div><div><h2>${escape(E.cluePerson(match,t))}، أعطِ كلمة!</h2><p><b>${escape(E.guessPerson(match,t))}</b> يحاول يعرف اللاعب.</p></div></div><button class="btn btn-dark next-hint" data-action="next-hint">قلنا التلميح… دور الفريق الثاني ${icon('switch')}</button><details class="hint-details"><summary>تفضّلوا تكتبوا الكلمة؟ <span>اختياري</span></summary><form id="hint-form"><label for="hint-input" class="sr-only">تلميح من كلمة واحدة</label><input id="hint-input" autocomplete="off" maxlength="32" placeholder="اكتب كلمة واحدة" enterkeyhint="send"><button type="submit" class="btn btn-outline">إرسال ${icon('arrow')}</button></form><p>بدون مسافات، وبدون تكرار كلمة من نفس الجولة.</p></details></div><div class="judge-zone"><div class="judge-heading"><h3>${icon('trophy')} يا حكم، مين عرفه؟</h3><span>أول إجابة صحيحة = نقطة</span></div><div class="award-buttons">${match.config.teams.map((team,i)=>`<button class="award-btn team-${i}" data-action="award" data-team="${i}"><span class="award-check">${icon('check')}</span><span><small>إجابة صحيحة</small><b>${escape(team.name)}</b></span><strong>+١</strong></button>`).join('')}</div></div>`}<div class="round-bottom"><div class="hint-counts"><span><i class="dot team-0"></i>${escape(match.config.teams[0].name)}: ${num(c.clues[0])}</span><span><i class="dot team-1"></i>${escape(match.config.teams[1].name)}: ${num(c.clues[1])}</span><small>تلميحات</small></div><button class="text-btn muted" data-action="skip-round">تخطّي الجولة ${icon('arrow')}</button></div>${c.hints.some(h=>h.word)?`<div class="hint-log"><span>الكلمات السابقة</span>${c.hints.filter(h=>h.word).map(h=>`<span class="hint-word team-${h.team}">${escape(h.word)}</span>`).join('')}</div>`:''}</div>`;}
function resultView(){const result=match.current.outcome,winner=result.winner,won=winner!==null,target=E.matchWinner(match)!==-1;return `<div class="game-stage result-stage ${won?'celebrate':''}"><div class="center-icon ${won?'lime':''}">${icon(won?'trophy':result.reason==='timeout'?'clock':'switch')}</div><span class="eyebrow">${target?'وصلتم لخط النهاية':won?'قولوا جوووول!':result.reason==='timeout'?'صافرة النهاية':'نحاول باللي بعدها'}</span><h1>${won?`نقطة لـ<span class="team-text-${winner}">${escape(match.config.teams[winner].name)}</span>`:result.reason==='timeout'?'خلص الوقت!':'الجولة مرّت'}</h1><p>${won?'إجابة صحيحة، وتستاهل نقطة.':'بدون نقاط للفريقين في هذه الجولة.'}</p><div class="answer-card"><span>اللاعب كان</span>${playerPortrait(match.current.player)}<h2>${escape(match.current.player.name)}</h2><div>${match.current.player.difficulty==='custom'?'من قائمتكم الخاصة':DIFFICULTY[match.current.player.difficulty]}<i></i>${num(match.current.clues[0]+match.current.clues[1])} تلميحات مسجّلة</div>${photoCredit(match.current.player)}</div><button class="btn btn-dark btn-lg" data-action="continue">${target?'شوفوا النتيجة النهائية':'الجولة الجايّة'} ${icon(target?'trophy':'arrow')}</button>${!target?'<p class="safe-note">'+icon('switch')+' الأدوار بتتبدّل بالجولة الجايّة.</p>':''}${won?'<button class="text-btn muted undo-btn" data-action="undo">'+icon('reset')+' تراجع عن احتساب النقطة</button>':''}</div>`;}
function finishedView(){const scores=match.scores,tie=scores[0]===scores[1],winner=tie?null:scores[0]>scores[1]?0:1,complete=match.endReason==='target';const title=tie?'تعادل… بدها إعادة!':complete?`${escape(match.config.teams[winner].name)} أبطال الملعب!`:`${escape(match.config.teams[winner].name)} في الصدارة`;return `<div class="finish-stage"><div class="winner-graphic">${icon('trophy')}<span>✦</span><i>✦</i></div><span class="eyebrow">${complete?'المباراة إلها أبطال':'انتهت المباراة'}</span><h1>${title}</h1><p>${match.endReason==='exhausted'?'خلصت الأسماء المختارة. ابدأوا مباراة جديدة بمجموعة أكبر.':complete?'كلمات قليلة، وذاكرة كروية كبيرة. يعطيكم العافية!':'هذه نتيجة الجولات المكتملة. جاهزين لتحدٍّ جديد؟'}</p><div class="final-scores"><span class="team-text-0">${num(scores[0])}</span><i>:</i><span class="team-text-1">${num(scores[1])}</span></div><div class="summary-stats"><div><strong>${num(match.history.length)}</strong><span>جولات</span></div><div><strong>${num(match.history.reduce((n,r)=>n+r.clues[0]+r.clues[1],0))}</strong><span>تلميحات</span></div><div><strong>${num(match.history.filter(r=>r.winner!==null).length)}</strong><span>إجابات صحيحة</span></div></div><div class="finish-actions"><button class="btn btn-dark btn-lg" data-action="rematch">نلعب كمان مرة؟ ${icon('reset')}</button><button class="btn btn-outline" data-action="setup">تغيير الإعدادات</button></div>${match.history.length?`<details class="history"><summary>دفتر المباراة <span>${num(match.history.length)} جولات ${icon('chevron')}</span></summary><ol>${match.history.map(round=>`<li><span class="history-number">${num(round.number)}</span><b>${escape(round.player.name)}</b><span class="${round.winner!==null?`team-text-${round.winner}`:'muted'}">${round.winner!==null?escape(match.config.teams[round.winner].name):round.reason==='timeout'?'انتهى الوقت':'تخطّي'}</span></li>`).join('')}</ol></details>`:''}<button class="text-btn muted" data-action="home">الرجوع للرئيسية</button></div>`;}

function paintTimer(){if(view!=='match'||match?.phase!=='playing')return;const seconds=E.remaining(match),timer=$('#timer');if(timer){timer.textContent=timeLabel(seconds);timer.classList.toggle('urgent',seconds!==null&&seconds<=10&&!match.current.paused);$('#time-progress').style.width=seconds===null?'100%':`${Math.max(0,Math.min(100,seconds/match.config.seconds*100))}%`;$('#time-progress').classList.toggle('urgent',seconds!==null&&seconds<=10);}
  if(seconds!==null&&!match.current.paused){const ceil=Math.ceil(seconds);if(ceil<=5&&ceil>0&&lastBeep!==ceil){lastBeep=ceil;beep('tick');}if(seconds<=0){beep('end');announce('انتهى وقت الجولة');update(E.resolveRound(match,null,'timeout'));}}
}
function sendHint(word=''){try{paintTimer();if(match.phase!=='playing')return;update(E.addHint(match,word));beep();announce(`دور فريق ${match.config.teams[match.current.turn].name}`);}catch(error){toast(error.message);}}
function openModal(html){hideSecret();$('#modal-content').innerHTML=html;$('#modal').showModal();}
function closeModal(){if($('#modal').open)$('#modal').close();modalCallback=null;}
function confirmDialog(title,message,label,callback){modalCallback=callback;openModal(`<div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="إغلاق">${icon('close')}</button></div><p>${message}</p><div class="modal-actions"><button class="btn btn-dark" data-action="confirm">${label}</button><button class="btn btn-outline" data-action="close-modal">خلّينا نكمّل</button></div>`);}
function showRules(){if(match?.phase==='playing'&&!match.current.paused){match=E.pause(match);save();if(view==='match')render();}openModal(`<div class="modal-header"><div><span class="eyebrow">سهلة… بس بدها ذكاء</span><h2>كيف نلعب «كلمة وبس»؟</h2></div><button class="icon-btn" data-action="close-modal" aria-label="إغلاق">${icon('close')}</button></div><ol class="rules-list"><li><b>فريقين وحكم</b><p>كل فريق شخصين. الحكم يمسك جهاز واحد ويسجّل النتيجة.</p></li><li><b>نفس اللاعب، سرّ واحد</b><p>شخص واحد من كل فريق يكشف صورة اللاعب واسمه بالضغط المطوّل. المخمّنان ما يشوفوا الشاشة أثناء الكشف.</p></li><li><b>كلمة واحدة كل دور</b><p>الفريقان يتناوبان. المُلمّح يقول كلمة، وزميله يعطي تخمينًا، ثم الحكم يبدّل الدور. استمروا لحد الإجابة الصحيحة أو نهاية الوقت.</p></li><li><b>أول إجابة صح تكسب</b><p>الحكم يضغط اسم الفريق الذي عرف اللاعب أولًا. نقطة لكل إجابة، والأدوار تتبدّل في كل جولة.</p></li></ol><div class="rules-warning"><b>خلّوها تحدّي عادل</b><p>ممنوع اسم اللاعب أو جزء منه، تهجئة الاسم، الإشارات، أو أكثر من كلمة. ما نكرّر تلميح بنفس الجولة. الحكم يفصل في صحة التلميح والإجابة.</p></div><div class="rules-example"><span>مثال</span><p>«أرجنتيني» ← تخمين ← «يسار» ← تخمين جديد</p><small>التلميحات تُقال بصوتكم؛ الكتابة اختيارية.</small></div><button class="btn btn-dark full-width" data-action="close-modal">وصلت… يلا حماس ${icon('check')}</button>`);}

document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;switch(action){
  case 'home':if(view==='setup')setupConfig=configFromForm();if(match?.phase==='playing'){match=E.pause(match);save();}go('home');break;
  case 'setup':if(match?.phase==='playing'){match=E.pause(match);save();}if(match)setupConfig=structuredClone(match.config);go('setup');break;
  case 'resume-match':go('match');break;
  case 'sound':sound=!sound;try{localStorage.setItem(SOUND_KEY,sound?'on':'off');}catch{}soundIcon();if(sound)beep();toast(sound?'الصوت شغّال':'الصوت مطفأ');break;
  case 'rules':showRules();break;
  case 'close-modal':closeModal();break;
  case 'confirm':{const callback=modalCallback;closeModal();callback?.();break;}
  case 'acknowledge':hideSecret();update(E.acknowledge(match));break;
  case 'replace-player':confirmDialog('نختار لاعب ثاني؟','الفريقان رح يشوفوا اسمًا جديدًا. اللاعب الحالي ما رح يتكرر في هذه المباراة.','غيّر اللاعب',()=>update(E.nextRound(match,{replace:true})));break;
  case 'start-round':lastBeep=-1;beep();update(E.startRound(match));break;
  case 'pause':if(match.phase==='playing'){paintTimer();if(match.phase==='playing')update(match.current.paused?E.resume(match):E.pause(match));}break;
  case 'next-hint':sendHint();break;
  case 'award':paintTimer();if(match.phase==='playing'&&!match.current.paused){beep('win');const team=Number(button.dataset.team);announce(`نقطة لفريق ${match.config.teams[team].name}`);update(E.resolveRound(match,team,'correct'));}break;
  case 'skip-round':if(match.phase==='playing'){match=E.pause(match);save();render();confirmDialog('نتخطّى هذه الجولة؟','رح نكشف اسم اللاعب وتنتهي الجولة بدون نقطة لأي فريق.','تخطّي الجولة',()=>update(E.resolveRound(match,null,'skip')));}break;
  case 'continue':update(E.continueMatch(match));window.scrollTo({top:0,behavior:'instant'});break;
  case 'undo':update(E.undoResult(match));toast('تم إلغاء النقطة. اضغط متابعة لإكمال نفس الجولة.');break;
  case 'end-match':if(match.phase==='playing'){match=E.pause(match);save();render();}confirmDialog('ننهي المباراة؟','رح نعرض النتيجة الحالية ودفتر الجولات المكتملة.','إنهاء وعرض النتيجة',()=>update(E.finishMatch(match)));break;
  case 'rematch':match=E.createMatch(match.config,PLAYERS);save();go('match');break;
}});
document.addEventListener('submit',event=>{if(event.target.id==='hint-form'){event.preventDefault();const input=$('#hint-input');if(!input.value.trim()){toast('اكتب كلمة أولًا، أو بدّل الدور بالزر الرئيسي.');return;}sendHint(input.value);}});
document.addEventListener('error',event=>{const image=event.target;if(image?.matches?.('img.player-photo')){image.hidden=true;image.closest('.portrait-frame')?.classList.add('photo-missing');}},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape')hideSecret();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){hideSecret();if(match?.phase==='playing'&&!match.current.paused){match=E.pause(match);save();if(view==='match')render();}}});
window.addEventListener('blur',hideSecret);
window.addEventListener('pagehide',()=>{hideSecret();if(match?.phase==='playing'){match=E.pause(match);save();}});
document.addEventListener('kalma:before-update',()=>{hideSecret();if(match?.phase==='playing')match=E.pause(match);save();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal'))closeModal();});
$('#modal').addEventListener('close',()=>{modalCallback=null;});
setInterval(paintTimer,200);
render();
